"""`.Tex Body`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Tex Body'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Main texture', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Main texture (dark)', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Color mask', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Detail mask', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Line mask', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Alpha mask', 'NodeSocketColor')
    t.socket('OUTPUT', 'Alpha mask (SFW)', 'NodeSocketColor')
    t.socket('OUTPUT', 'Overlay 1', 'NodeSocketColor')
    t.socket('OUTPUT', 'Overlay 1 (alpha)', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Overlay 2', 'NodeSocketColor')
    t.socket('OUTPUT', 'Overlay 2 (alpha)', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Toon shading', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame.005', props={
        'location': (-53.200012, 232.2),
        'width': 921.1946,
        'height': 171.0,
        'label': 'Overlays from the textures folder',
        'use_custom_color': True,
        'color': (0.14992589, 0.39358228, 0.6018082),
    })
    t.node('NodeFrame', 'Node', props={
        'location': (58.0, -523.0),
        'width': 555.8114,
        'label': 'Permalight mask (R = light, B = dark, dark takes priority)',
        'use_custom_color': True,
        'color': (0.47511104, 0.45669952, 0.33585504),
    })
    t.node('NodeFrame', 'Frame.004', props={
        'location': (-187.6, 31.399994),
        'width': 813.074,
        'height': 508.0,
        'label': 'Textures from the texture folder',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (1131.9207, 93.45544),
    })
    t.node('ShaderNodeTexImage', '_T3.png', parent='Frame.005', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (346.02866, -45.1577),
        'width': 541.1946,
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_T6.png', parent='Frame.005', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (349.7704, -104.33806),
        'width': 541.1946,
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', 'perma', parent='Node', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (30.160843, -45.37323),
        'width': 495.81143,
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeGroup', 'Bodypos', parent='Frame.005', props={
        'node_tree': lib.group('.Body overlay positioning'),
        'location': (30.070374, -42.77945),
        'width': 240.8974,
    })
    t.node('ShaderNodeUVMap', 'UV Map.001', parent='Frame.004', props={
        'location': (29.935852, -248.93086),
        'width': 150.0,
    })
    t.node('ShaderNodeGroup', 'shade', props={
        'node_tree': lib.group('.Toon shading'),
        'location': (710.5806, -323.09686),
        'width': 247.78687,
    })
    t.node('ShaderNodeTexImage', '_DM.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (285.44336, -178.92448),
        'width': 480.9713,
        'label': 'detail mask',
        'hide': True,
    })
    t.node('ShaderNodeTexImage', '_AM.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (288.1285, -283.85022),
        'width': 479.43573,
        'label': 'alpha mask',
        'hide': True,
        'image': lib.image('Template: Placeholder'),
        'image_user': {
            'frame_duration': 1,
            'frame_offset': -1,
        },
    })
    t.node('ShaderNodeTexImage', 'Node.001', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (296.18555, -338.37997),
        'width': 475.3158,
        'label': 'SFW alpha mask',
        'hide': True,
        'image': lib.image('Template: SFW alpha mask.png'),
        'image_user': {
            'frame_duration': 1,
            'frame_offset': -1,
        },
    })
    t.node('ShaderNodeTexImage', '_NMP_CNV.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (292.69617, -393.9687),
        'width': 489.18396,
        'label': 'Normal map',
        'hide': True,
    })
    t.node('ShaderNodeTexImage', '_NMPD_CNV.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (290.8435, -453.06555),
        'width': 492.27393,
        'label': 'normal map detail',
        'hide': True,
        'image': lib.image('Template: Normal detail placeholder'),
    })
    t.node('ShaderNodeTexImage', '_LM.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (280.52368, -226.78189),
        'width': 487.1743,
        'label': 'line mask',
        'hide': True,
    })
    t.node('ShaderNodeTexImage', '_ST_CT.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (275.43323, -44.727783),
        'width': 491.46423,
        'label': 'main texture',
        'hide': True,
        'image': lib.image('Template: Placeholder'),
    })
    t.node('ShaderNodeTexImage', '_ST_DT.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (275.43323, -93.068405),
        'width': 491.46423,
        'label': 'main texture dark',
        'hide': True,
        'show_texture': True,
        'image': lib.image('Template: Placeholder'),
    })
    t.node('ShaderNodeTexImage', '_CM.png', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (276.02356, -138.96216),
        'width': 491.46423,
        'label': 'color mask',
        'hide': True,
    })

    t.link('_LM.png', 'Color', 'Group Output', 'Line mask')
    t.link('_DM.png', 'Color', 'Group Output', 'Detail mask')
    t.link('_CM.png', 'Color', 'Group Output', 'Color mask')
    t.link('_ST_CT.png', 'Color', 'Group Output', 'Main texture')
    t.link('_T3.png', 'Alpha', 'Group Output', 'Overlay 1 (alpha)')
    t.link('_T6.png', 'Alpha', 'Group Output', 'Overlay 2 (alpha)')
    t.link('_T3.png', 'Color', 'Group Output', 'Overlay 1')
    t.link('_T6.png', 'Color', 'Group Output', 'Overlay 2')
    t.link('Node.001', 'Color', 'Group Output', 'Alpha mask (SFW)')
    t.link('_AM.png', 'Color', 'Group Output', 'Alpha mask')
    t.link('UV Map.001', 'UV', '_AM.png', 'Vector')
    t.link('UV Map.001', 'UV', 'Node.001', 'Vector')
    t.link('_ST_DT.png', 'Color', 'Group Output', 'Main texture (dark)')
    t.link('Bodypos', 'Overlay 1', '_T3.png', 'Vector')
    t.link('Bodypos', 'Overlay 2', '_T6.png', 'Vector')
    t.link('perma', 'Color', 'shade', 'Permalight mask')
    t.link('shade', 'Toon shading', 'Group Output', 'Toon shading')
    t.link('_NMP_CNV.png', 'Color', 'shade', 'Normal color')
    t.link('_NMP_CNV.png', 'Alpha', 'shade', 'Normal alpha')
    t.link('_NMPD_CNV.png', 'Color', 'shade', 'Normal detail color')
    t.link('_NMPD_CNV.png', 'Alpha', 'shade', 'Normal detail alpha')
    t.link('UV Map.001', 'UV', '_CM.png', 'Vector')
    t.link('UV Map.001', 'UV', '_DM.png', 'Vector')
    t.link('UV Map.001', 'UV', '_LM.png', 'Vector')
    t.link('UV Map.001', 'UV', '_NMP_CNV.png', 'Vector')
    t.link('UV Map.001', 'UV', '_NMPD_CNV.png', 'Vector')
    return t
